python3 -c "
import json
with open('/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-be-idea-gen-0515-2-projects-importance-margin-vla-compress/cedecd54-cbc6-4604-b349-69b930945917/tool-results/mcp-agent-ml-research-read_registry-1779572257256.txt') as f:
    raw = json.load(f)['result']
data = json.loads(raw)
exps = data['data']['experiments']
print(f'Total experiments: {len(exps)}')

long_exps = {k: v for k, v in exps.items() if 'long' in k or 'libero_10' in k}
print(f'Long/libero_10 experiments: {len(long_exps)}')
print()

# Categorize
baselines = {}
random_prune = {}
l2norm_prune = {}
attn_prune = {}
other = {}

for k, v in long_exps.items():
    if 'baseline' in k:
        baselines[k] = v
    elif 'random' in k:
        random_prune[k] = v
    elif 'l2norm' in k:
        l2norm_prune[k] = v
    elif 'attn' in k:
        attn_prune[k] = v
    else:
        other[k] = v

def fmt(k, v):
    m = v.get('metrics', {})
    sr = m.get('success_rate', m.get('overall_SR', m.get('overall_sr', 'N/A')))
    status = v.get('status', 'N/A')
    conclusion = v.get('conclusion', 'N/A')
    return f'  {k}: SR={sr}, status={status}, conclusion={conclusion}'

print('=== BASELINES (k=1.0) ===')
for k, v in sorted(baselines.items()):
    print(fmt(k, v))

print()
print('=== RANDOM PRUNING ===')
for k, v in sorted(random_prune.items()):
    print(fmt(k, v))

print()
print('=== L2NORM PRUNING ===')
for k, v in sorted(l2norm_prune.items()):
    print(fmt(k, v))

print()
print('=== ATTENTION PRUNING ===')
for k, v in sorted(attn_prune.items()):
    print(fmt(k, v))

print()
print('=== OTHER ===')
for k, v in sorted(other.items()):
    print(fmt(k, v))
